49	fn get_snapshot_from_diagnostic(diagnostic: &Diagnostic) -> String {
50	    let code = match &diagnostic.code {
51	        Some(NumberOrString::Number(code)) => code.to_string(),
52	        Some(NumberOrString::String(code)) => code.clone(),
53	        None => "None".to_string(),
54	    };
55	    let code_description_href = match &diagnostic.code_description {
56	        Some(CodeDescription { href }) => href.to_string(),
57	        None => "None".to_string(),
58	    };
59	    let message = diagnostic.message.clone();
60	    let range = diagnostic.range;
61	    let related_information = match &diagnostic.related_information {
62	        Some(infos) => {
63	            infos
64	                .iter()
65	                .enumerate()
66	                .map(|(i, info)| {
67	                    let mut result = String::new();
68	                    write!(result, "related_information[{}].message: {:?}", i, info.message)
69	                        .unwrap();
70	                    // replace everything between `file://` and `oxc_language_server` with `<variable>`, to avoid
71	                    // the absolute path causing snapshot test failures in different environments
72	                    let location = get_snapshot_safe_uri(&info.location.uri);
73	
74	                    write!(result, "\nrelated_information[{i}].location.uri: {location:?}",)
75	                        .unwrap();
76	                    write!(
77	                        result,
78	                        "\nrelated_information[{}].location.range: {:?}",
79	                        i, info.location.range
80	                    )
81	                    .unwrap();
82	                    result
83	                })
84	                .collect::<Vec<_>>()
85	                .join("\n")
86	        }
87	        None => "related_information: None".to_string(),
88	    };
89	    let severity = diagnostic.severity;
90	    let source = &diagnostic.source;
91	    let tags = &diagnostic.tags;
92	
93	    format!(
94	        r"
95	code: {code:?}
96	code_description.href: {code_description_href:?}
97	message: {message:?}
98	range: {range:?}
99	{related_information}
100	severity: {severity:?}
101	source: {source:?}
102	tags: {tags:?}"
103	    )
104	}
